test('actual client returns from a throttled hidden page without catch-up interval or finish bells',async()=>{
 const f=await clientFixture();await f.get('start').onclick();f.document.hidden=true;await f.emitDoc('visibilitychange');f.setNow(190000);f.document.hidden=false;await f.emitDoc('visibilitychange');assert.equal(f.engines[0].bells,0);assert.equal(f.get('clock').textContent,'01:50');await f.tick();assert.equal(f.engines[0].bells,0);f.setNow(240000);await f.tick();assert.equal(f.engines[0].bells,1,'only a genuinely future visible interval may ring');
 f.document.hidden=true;await f.emitDoc('visibilitychange');f.setNow(400000);f.document.hidden=false;await f.emitDoc('visibilitychange');assert.equal(f.state().state,'finished');assert.equal(f.engines[0].bells,1);assert.match(f.get('practice-status').textContent,/后台结束/);await f.tick();assert.equal(f.engines[0].bells,1);
});
test('actual client BFCache return requires explicit ownership recovery and excludes time away',async()=>{
 const f=await clientFixture();await f.click('start');f.setNow(20000);await f.emitWindow('pagehide',{persisted:true});assert.equal(f.intervals.size,0);assert.equal(f.engines[0].closed,true);f.setNow(190000);await f.emitWindow('pageshow',{persisted:true});assert.equal(f.intervals.size,1);assert.equal(f.engines.length,2);assert.equal(f.engines[1].plays,0);assert.equal(f.engines[1].bells,0);assert.equal(f.state().state,'idle');assert.equal(f.get('resume-session').hidden,false);await f.click('restore-session');assert.equal(f.state().state,'paused');assert.equal(f.state().meditationElapsedMs,20000);assert.equal(f.get('clock').textContent,'04:40');assert.equal(f.engines[1].plays,0);assert.equal(f.engines[1].bells,0);await f.click('resume');f.setNow(200000);await f.tick();assert.equal(f.get('clock').textContent,'04:30');await f.click('play-sound');assert.equal(f.engines[1].plays,1);assert.match(f.get('sound-state').textContent,/正在试听/);
});
test('BFCache return after old deadline does not fabricate completion or replay audio',async()=>{
 const f=await clientFixture();await f.click('start');await f.emitWindow('pagehide',{persisted:true});f.setNow(500000);await f.emitWindow('pageshow',{persisted:true});assert.equal(f.state().state,'idle');await f.tick();assert.equal(f.store.read().history.length,0);assert.equal(f.engines[1].plays,0);assert.equal(f.engines[1].bells,0);assert.match(f.get('practice-status').textContent,/未补记/);await f.click('restore-session');assert.equal(f.state().state,'paused');assert.equal(f.state().meditationElapsedMs,0);
});
test('page lifecycle invalidates pending audio unlock/start and pending sound-play UI updates',async()=>{
 const f=await clientFixture();f.deferPrepare();const start=f.get('start').onclick();await f.settle();await f.emitWindow('pagehide',{persisted:true});await f.emitWindow('pageshow',{persisted:true});assert.ok(f.pendingPrepare.length);f.pendingPrepare.shift()();await start;assert.equal(f.state().state,'idle');assert.equal(f.intervals.size,1);f.deferPrepare(false);f.deferPlay();const play=f.get('play-sound').onclick();await f.emitWindow('pagehide',{persisted:true});await f.emitWindow('pageshow',{persisted:true});f.pendingPlay.shift()();await play;assert.doesNotMatch(f.get('sound-state').textContent,/正在试听/);assert.equal(f.engines.at(-1).plays,0);
});
test('clock is non-live, updates only on displayed-second change, and successful completion announces once',async()=>{
 const html=await(await createPracticeApplication().fetch(new Request('https://x/practice/timer'))).text();assert.match(html,/id="clock" aria-live="off"/);const f=await clientFixture();await f.get('start').onclick();const writes=f.get('clock').writes;await f.tick();await f.tick();assert.equal(f.get('clock').writes,writes);const before=f.get('practice-status').writes;f.setNow(300000);await f.tick();assert.equal(f.engines[0].bells,1);assert.match(f.get('practice-status').textContent,/计时完成/);assert.equal(f.get('practice-status').writes,before+1);await f.tick();assert.equal(f.get('practice-status').writes,before+1);
});

test('actual client reflects natural sound completion while muting does not pretend playback stopped',async()=>{const f=await clientFixture();await f.get('play-sound').onclick();assert.match(f.get('sound-state').textContent,/正在试听/);await f.get('mute').onclick();await f.tick();assert.match(f.get('sound-state').textContent,/已静音/);assert.equal(f.engines[0].playing,true);assert.equal(f.engines[0].muted,true);assert.equal(f.get('sound-quick').hidden,false);f.engines[0].playing=false;await f.tick();assert.equal(f.get('sound-state').textContent,'声音已结束');assert.equal(f.get('play-sound').textContent,'播放声音')});

test('same-page sound navigation retains the timer and announces completion in the visible sound section',async()=>{const f=await clientFixture();await f.get('start').onclick();f.get('nav-sounds').onclick({preventDefault(){}});assert.equal(f.get('timer-panel').hidden,true);assert.equal(f.state().state,'running');f.setNow(300000);await f.tick();assert.equal(f.state().state,'finished');assert.match(f.get('sound-status').textContent,/计时完成/);f.get('nav-timer').onclick({preventDefault(){}});assert.equal(f.get('timer-panel').hidden,false);assert.equal(f.get('clock').textContent,'00:00')});

