test('actual client records one early-ended session, excluding pause and preparation',async()=>{const f=await clientFixture();await f.get('start').onclick();f.setNow(10000);await f.get('pause').onclick();f.setNow(50000);await f.get('resume').onclick();f.setNow(60000);await f.get('end').onclick();await f.get('end').onclick();const d=f.store.read();assert.equal(d.history.length,1);assert.equal(d.history[0].outcome,'ended');assert.equal(d.history[0].elapsedSeconds,20);assert.equal(d.activeSession,null)});
