test('restored preparation retains frozen cues and never replays a cue before explicit continuation',async()=>{const f=await clientFixture();f.get('preparation').value='10';await f.get('preparation').onchange();f.get('start-cue').value='recorded-mokugyo';await f.get('start-cue').onchange();await f.click('start');f.setNow(5000);await f.emitWindow('pagehide',{persisted:true});const saved=f.store.read().activeSession;assert.equal(saved.preparationRemainingMs,5000);assert.equal(saved.cuePlan.startCue,'recorded-mokugyo');await f.store.setPreferences({startCue:'recorded-mokugyo',endCue:'silent'});f.setNow(50000);await f.emitWindow('pageshow',{persisted:true});await f.click('restore-session');assert.equal(f.state().preparationRemainingMs,5000);assert.equal(f.state().state,'paused');assert.equal(f.get('start-cue').value,'recorded-mokugyo');assert.equal(f.engines[1].bells,0);await f.click('resume');await f.settle();f.setNow(55000);await f.tick();assert.deepEqual(f.engines[1].cueKinds,['recorded-mokugyo'])});
test('actual client clock discontinuity pauses at confirmed time without adding completion',async()=>{const f=await clientFixture();await f.click('start');f.setNow(10000);await f.tick();const elapsed=f.state().meditationElapsedMs;f.setWall(999999);await f.tick();assert.equal(f.state().state,'paused');assert.equal(f.state().clockUncertain,true);assert.equal(f.state().meditationElapsedMs,elapsed);assert.equal(f.engines[0].playing,false);assert.equal(f.engines[0].cuePlaying,false);assert.equal(f.store.read().history.length,0);assert.match(f.get('practice-status').textContent,/时间.*异常|时钟变化/);await f.click('resume');assert.equal(f.state().clockUncertain,false);assert.equal(f.state().state,'running')});

