function gatedLocks(){const base=fakeLocks();let gate=null,denied=false;return{denyNext(){denied=true},holdNext(){let release;const promise=new Promise(resolve=>{release=resolve});gate={promise,release};return()=>release()},request(name,options,fn){if(name==='dharmagate.practice.data'&&denied){denied=false;return Promise.reject(Error('LOCK_DENIED'))}if(name==='dharmagate.practice.data'&&gate){const current=gate;gate=null;return current.promise.then(()=>base.request(name,options,fn))}return base.request(name,options,fn)}}}
test('stopping after immediate card playback cannot be undone by a delayed preference save',async()=>{const locks=gatedLocks(),f=await clientFixture({locksHandle:locks}),release=locks.holdNext(),pending=f.get('preview-sound-recorded-bowl-rubbed').onclick();await f.settle();assert.equal(f.engines[0].plays,1);assert.equal(f.engines[0].backgroundKind,'recorded-bowl-rubbed');await f.click('stop-sound');release();await pending;await f.settle();assert.equal(f.engines[0].plays,1,'preference completion must not replay the sound');assert.equal(f.engines[0].playing,false);assert.equal(f.engines[0].backgroundKind,null);assert.equal(f.get('sound-state').textContent,'声音已停止')});
test('a newer struck-bowl audition remains current after an older rubbed-bowl preference save finishes',async()=>{const locks=gatedLocks(),f=await clientFixture({locksHandle:locks}),release=locks.holdNext(),first=f.get('preview-sound-recorded-bowl-rubbed').onclick();await f.settle();await f.click('preview-sound-recorded-bowl-struck');release();await first;await f.settle();assert.equal(f.engines[0].plays,2,'each explicit audition starts once; old persistence must not replay rubbed bowl');assert.equal(f.engines[0].cuePlaying,true);assert.equal(f.engines[0].backgroundKind,null);assert.equal(f.get('card-recorded-bowl-rubbed').dataset.playing,'false');assert.equal(f.get('card-recorded-bowl-struck').dataset.playing,'true')});
test('stopping while audition checkpoint awaits storage cannot relabel sound as playing',async()=>{const locks=gatedLocks(),f=await clientFixture({locksHandle:locks});await f.click('start');const release=locks.holdNext(),pending=f.get('play-sound').onclick();await f.settle();assert.equal(f.engines[0].plays,1);await f.click('stop-sound');release();await pending;await f.settle();assert.equal(f.engines[0].playing,false);assert.equal(f.get('sound-state').textContent,'声音已停止');assert.equal(f.get('play-sound').textContent,'播放声音')});

