const backupRow={id:'restore_fixture_1',startedAt:0,endedAt:60000,plannedSeconds:60,elapsedSeconds:60,outcome:'completed',practiceId:'quiet-sitting',sound:'silent'};
function fixtureBackup(f,rows=[backupRow]){const data=JSON.parse(f.store.exportData());data.history=rows;data.activeSession=null;data.unsavedCount=0;return JSON.stringify(data)}
async function chooseBackup(f,text){f.get('backup-file').files=[{size:Buffer.byteLength(text),text:async()=>text}];await f.get('backup-file').onchange();await f.settle()}
