test('prepared export is revoked on pagehide and cannot create a late download',async()=>{const f=await clientFixture();await f.click('nav-history');await f.click('export-history');await f.click('confirm-export');await f.emitWindow('pagehide',{persisted:true});assert.equal(f.revoked.length,1);assert.equal(f.get('export-copy-text').value,'');await f.click('export-download-link');assert.equal(f.downloads.length,0)});
function readingClick(href,extra={}){const link={href,target:'',hasAttribute(){return false},...extra},event={button:0,defaultPrevented:false,target:{closest:()=>link},preventDefault(){this.defaultPrevented=true}};return{link,event}}
